#!/usr/bin/env python3
"""Context Gatekeeper - Summarizes conversation history for token efficiency."""

import argparse
import sys
from pathlib import Path
from datetime import datetime, timezone


def parse_args():
    parser = argparse.ArgumentParser(
        description='Context Gatekeeper: Summarize conversation history'
    )
    parser.add_argument(
        '--history', 
        type=str,
        default=None,
        help='Path to history file (reads from stdin if not provided)'
    )
    parser.add_argument(
        '--summary',
        type=str,
        default='context/current-summary.md',
        help='Output path for the summary markdown file'
    )
    parser.add_argument(
        '--max-sentences',
        type=int,
        default=6,
        help='Maximum sentences in summary (default: 6)'
    )
    parser.add_argument(
        '--last-turns',
        type=int,
        default=4,
        help='Number of last turns to include (default: 4)'
    )
    return parser.parse_args()


def read_history(history_path):
    """Read history from file or stdin."""
    if history_path is None:
        return sys.stdin.read()

    path = Path(history_path)
    if not path.exists():
        print(f"Warning: History file '{history_path}' not found. Creating empty summary.", file=sys.stderr)
        return ""

    return path.read_text(encoding='utf-8')


def parse_turns(content):
    """Parse conversation turns from history content."""
    turns = []
    for line in content.strip().split('\n'):
        line = line.strip()
        if not line:
            continue
        # Handle malformed lines - try to extract role and message
        if ':' in line:
            parts = line.split(':', 1)
            role = parts[0].strip().upper()
            message = parts[1].strip() if len(parts) > 1 else ''
            if role in ('USER', 'ASSISTANT'):
                turns.append({'role': role, 'message': message})
            else:
                # Keep malformed lines but mark them
                turns.append({'role': 'UNKNOWN', 'message': line})
        else:
            # Line without colon - treat as UNKNOWN
            turns.append({'role': 'UNKNOWN', 'message': line})
    return turns


def extract_pending_items(turns):
    """Extract open actions and pending items from conversation."""
    pending = []
    keywords = ['precisa', 'precisamos', 'deve', 'falta', 'fazer', 'testar', 
                'revisar', 'incluir', 'decidir', 'montar', 'listar', 'confirmo']

    for turn in turns:
        if turn['role'] == 'USER':
            msg_lower = turn['message'].lower()
            for keyword in keywords:
                if keyword in msg_lower:
                    if turn['message'] not in pending:
                        pending.append(turn['message'])
                    break

    # Also check for explicit action items
    for turn in turns:
        msg_lower = turn['message'].lower()
        if 'falta' in msg_lower or 'pendência' in msg_lower:
            pending.append(f"Ação solicitada: {turn['message']}")

    return pending if pending else ['Nenhuma pendência identificada no histórico recente.']


def generate_summary(turns, max_sentences=6):
    """Generate a compact summary of the conversation."""
    summary_points = []

    for turn in turns:
        if turn['role'] in ('USER', 'ASSISTANT'):
            msg = turn['message']
            # Split into sentences (simple approach)
            sentences = [s.strip() for s in msg.replace('\n', ' ').split('.') if s.strip()]
            for sent in sentences:
                if len(summary_points) < max_sentences:
                    summary_points.append(sent)
                else:
                    break
            if len(summary_points) >= max_sentences:
                break

    return summary_points


def get_last_turns(turns, n=4):
    """Get the last n turns of conversation."""
    return turns[-n:] if len(turns) >= n else turns


def format_summary(turns, pending_items, last_turns, max_sentences=6):
    """Format the complete markdown summary."""
    timestamp = datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%S+00:00')

    summary_points = generate_summary(turns, max_sentences)

    lines = [
        '# Context Gatekeeper',
        f'_Gerado: {timestamp}_',
        '',
        '## Resumo compacto'
    ]

    if summary_points:
        for point in summary_points:
            lines.append(f'- {point}')
    else:
        lines.append('- Nenhuma informação disponível.')

    lines.append('')
    lines.append('## Pendências e próximos passos')

    if pending_items:
        for item in pending_items:
            lines.append(f'- {item}')
    else:
        lines.append('- Nenhuma pendência identificada.')

    lines.append('')
    lines.append('## Últimos turnos')

    if last_turns:
        for turn in last_turns:
            lines.append(f'- {turn["role"]}: {turn["message"]}')
    else:
        lines.append('- Nenhum turno disponível.')

    lines.append('')

    return '\n'.join(lines)


def main():
    args = parse_args()

    # Read history
    history_content = read_history(args.history)

    # Parse turns
    turns = parse_turns(history_content)

    # Extract pending items
    pending_items = extract_pending_items(turns)

    # Get last turns
    last_turns = get_last_turns(turns, args.last_turns)

    # Generate formatted summary
    summary = format_summary(turns, pending_items, last_turns, args.max_sentences)

    # Write summary to file
    summary_path = Path(args.summary)
    summary_path.parent.mkdir(parents=True, exist_ok=True)
    summary_path.write_text(summary, encoding='utf-8')

    print(f"Summary written to: {args.summary}")


if __name__ == '__main__':
    main()
